#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);archive=File.join(client,'development/archived-orientation-folders');payload=Dir.glob(File.join(archive,'**/*')).select{|p|File.file?(p)&&!p.end_with?('.meta')&&File.basename(p)!='.DS_Store'};adapters=Dir.glob(File.join(client,'assets/**/*.ts')).select{|p|t=File.read(p,encoding:'UTF-8',invalid: :replace,undef: :replace,replace:'');t.match?(/(?:Widget|SafeArea|view\.getVisibleSize|orientation)/i)}.map{|p|p.delete_prefix(client+'/')};report={schemaVersion:1,archivePayloadFiles:payload.map{|p|p.delete_prefix(client+'/')},archiveMetaFiles:Dir.glob(File.join(archive,'**/*.meta')).length,activeAdapterFiles:adapters,checks:{archivePayloadEmpty:payload.empty?,singleOrientationAdapter:adapters.length==1},verdict:payload.empty?&&adapters.length==1 ? 'passed':'blocked-orientation-convergence'};out=File.join(root,'docs/generated/carch04-orientation-archive.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CARCH04 AUDITED: archive payload=#{payload.length}, adapter candidates=#{adapters.length}"
